};

const getImporterDir = (): string => {
  const error = new Error('Getting importer directory');
  const stackFrames = error.stack?.split('\n') || [];

  // Skip the first frame (this function) and the second frame (the caller of this function)
  // to get to the actual importer
  for (let i = 2; i < stackFrames.length; i++) {
    const frame = stackFrames[i]?.trim() || '';

    const match =
      STACK_FRAME_PATTERN_1.exec(frame) ||
      STACK_FRAME_PATTERN_2.exec(frame) ||
      STACK_FRAME_PATTERN_3.exec(frame);

    if (!match?.[1]) {
      continue;
    }

    let filePath = match[1].trim();

    if (filePath.startsWith('file://')) {
      filePath = fileURLToPath(filePath);
    }

    if (filePath === getScriptFile()) {
      continue;
    }

    if (pathExists(filePath)) {
      return path.dirname(filePath);
    }
  }

  return process.cwd();
};


const pathExists = (targetPath: string): boolean => {
  try {
    return fs.existsSync(targetPath);
  } catch {
    return false;
  }
};

const getImporterFile = (): string => {
  const error = new Error('Getting importer file');
  const stackFrames = error.stack?.split('\n') || [];

  // Skip the first frame (this function) and the second frame (the caller of this function)
  // to get to the actual importer
  for (let i = 2; i < stackFrames.length; i++) {
    const frame = stackFrames[i]?.trim() || '';
    const match = STACK_FRAME_PATTERN_3.exec(frame);
    if (!match?.[1]) {
      continue;
    }

    const filePath = match[1].startsWith('file://')
      ? fileURLToPath(match[1])
      : match[1];

    if (filePath === getScriptFile()) {
      continue;
    }

    return filePath;
  }

  return process.argv[1] || ''; // Fallback to main script
};

const getCallerDir = (): string => {
  // Return the current working directory of the Node.js process
  // This is the directory where the node command was executed from
  return process.cwd();
};

const getCallerFile = (): string => {
  // Return the path of the script that was run with Node.js
  return process.argv[1] || '';
};

const isDirectory = (targetPath: string): boolean => {
  if (!pathExists(targetPath)) {
    throw new Error(`Path does not exist: ${targetPath}`);
  }

  return fs.lstatSync(targetPath).isDirectory();
};

const readFile = (params: Readonly<{
  encoding?: BufferEncoding | null | undefined;
  path: string;
  throwError?: boolean;
}>): Buffer | null | string => {
  const {
    encoding = 'utf8',
    path: filePath,
    throwError = true,
  } = params;
  const exists = pathExists(filePath);
  if (!exists && throwError) {
    throw new Error(`File does not exist: ${filePath}`);
  }

  if (exists) {
    const isDir = isDirectory(filePath);
    if (isDir && throwError) {
      throw new Error(`Path is a directory, not a file: ${filePath}`);
    }
    if (!isDir) {
      const options = {
        encoding: encoding ?? undefined,
      };
      return fs.readFileSync(filePath, options);
    }
  }

  return null;
};

const createDir = (params: Readonly<{
  path: string;
  recursive?: boolean;
  throwError?: boolean;
}>): void => {
  const {
    path: dirPath,
    recursive = true,
    throwError = false,
  } = params;
  if (pathExists(dirPath) && throwError) {
    throw new Error(`Directory already exists: ${dirPath}`);
  }

  fs.mkdirSync(dirPath, { recursive });
};

const createFile = (params: Readonly<{
  content?: string;
  encoding?: BufferEncoding | null | undefined;
  path: string;
  replace?: boolean;
  throwError?: boolean;
}>): void => {
  const {
    content = '',
    encoding = 'utf8',
    path: filePath,
    replace = false,
    throwError = true,
  } = params;
  const exists = pathExists(filePath);
  if (exists && !replace && throwError) {
    const error = isDirectory(filePath)
      ? new Error(
          `A directory exists for this path, cannot create file: ${filePath}`
        )
      : new Error(
          `A file already exists for this path, cannot create file: ${filePath}`
        );
    throw error;
  }

  if (!exists || replace) {
    const options = {
      encoding: encoding ?? undefined,
    };

    fs.writeFileSync(filePath, content || '', options);
  }
};

const deletePath = (params: Readonly<{
  force?: boolean;
  path: string;
  recursive?: boolean;
  throwError?: boolean;
}>): void => {
  const {
    force = true,
    path: targetPath,
    recursive = true,
    throwError = true,
  } = params;
  const exists = pathExists(targetPath);
  if (!exists && throwError && !force) {
    throw new Error(`Path does not exist: ${targetPath}`);
  }

  if (exists) {
    const isDir = isDirectory(targetPath);
    if (isDir) {
      fs.rmSync(targetPath, { force, recursive });
    } else {
      fs.unlinkSync(targetPath);
    }
  }
};

const copyPath = (params: Readonly<{
  destinationPath: string;
  force?: boolean;
  recursive?: boolean;
  replace?: boolean;
  sourcePath: string;
  throwError?: boolean;
}>): void => {
  const {
    destinationPath,
    force = true,
    recursive = true,
    replace = false,
    sourcePath,
    throwError = true,
  } = params;
  const sourceExists = pathExists(sourcePath);
  if (!sourceExists && throwError) {
    throw new Error(`Source path does not exist: ${sourcePath}`);
  }

  const destinationExists = pathExists(destinationPath);
  if (destinationExists && throwError) {
    throw new Error(`Destination path already exists: ${destinationPath}`);
  }

  if (
    (sourceExists && !destinationExists) ||
    (sourceExists && destinationExists && replace)
  ) {
    if (replace) {
      deletePath({ force, path: destinationPath, recursive });
    }

    const isDir = isDirectory(sourcePath);
    if (isDir) {
      fs.cpSync(sourcePath, destinationPath, { force, recursive });
    } else {
      fs.copyFileSync(sourcePath, destinationPath);
    }
  }
};

const movePath = (params: Readonly<{
  destinationPath: string;
  force?: boolean;
  recursive?: boolean;
  replace?: boolean;
  sourcePath: string;
  throwError?: boolean;
}>): void => {
  const {
    destinationPath,
    force = true,
    recursive = true,
    replace = false,
    sourcePath,
    throwError = true,
  } = params;
  const sourceExists = pathExists(sourcePath);
  if (!sourceExists && throwError) {
