    const parentDir = path.dirname(currentDir);
    if (parentDir === currentDir) {
      // We've reached the filesystem root without finding the marker
      break;
    }
    currentDir = parentDir;
  }

  throw new Error(
    `Could not find project root directory (looking for ${marker})`
  );
};

